; Saving the player state and switching the player
; $9922-$99c4

; Then it resets the three scales and copies the status rows 22 to 24 of the screen to $4000 (player 1) or $4080 (player 2).
save_player_state
        lda current_player
        cmp #$02
        beq save_state_p2
        ldx #$08
save_state_p1_loop
        lda player_vars,x
        sta player1_state,x
        dex
        bne save_state_p1_loop
        jmp clear_scales
save_state_p2
        ldx #$08
save_state_p2_loop
        lda player_vars,x
        sta player2_state,x
        dex
        bne save_state_p2_loop
; Row 24 (MOWER OVERLOAD) gets spaces, empty cells.
clear_scales
        lda #$10
        sta cursor_col
        lda #$00
        sta cursor_colour
clear_scales_column
        lda #$22
        sta cursor_char
        lda #$16
        sta cursor_row
        jsr put_char
        inc cursor_row
        jsr put_char
        inc cursor_row
        lda #$20
        sta cursor_char
        jsr put_char
        inc cursor_col
        lda cursor_col
        cmp #$1f
        bne clear_scales_column
        lda #$00
        sta cursor_col
        lda #$16
        sta cursor_row
        jsr get_screen_address
save_status_rows_loop
        lda (screen_ptr),y              ; Reads row 22 to row 24: 120 characters from $0770.
        ldx current_player
        cpx #$02
        beq save_status_rows_p2
        sta status_p1,y
        jmp save_status_rows_next
save_status_rows_p2
        sta status_p2,y
save_status_rows_next
        iny
        cpy #$78
        bne save_status_rows_loop
        rts
; When player 2 loses the third mower, the game is over. Else the other player gets the turn: $8a1e loads the state and $8672 starts the lawn.
switch_player
        ldx #$f8                        ; Resets the stack.
        txs
        lda stick_count
        cmp #$01
        beq switch_player_save
        dec joy_port                    ; Changes the port: 1 to 0, 0 to 1.
        lda joy_port
        cmp #$ff
        bne switch_player_save
        lda #$01
        sta joy_port
switch_player_save
        inc mower_lender                ; The next mower of this player.
        jsr save_player_state
        lda mower_lender
        cmp #$04
        bne switch_player_next
        lda current_player
        cmp #$02
        bne switch_player_next
        jmp game_over
switch_player_next
        inc current_player              ; Player 1 to 2, player 2 to 1.
        lda current_player
        cmp #$03
        bne switch_player_start
        lda #$01
        sta current_player
switch_player_start
        jsr load_player_and_draw_status ; Loads the state of the new player and draws the status rows.
        jmp player_turn_intro
